 OUT.mkdir(parents=True,exist_ok=True);d2=ROOT/'poc/dlg-02/output/results.json';d3=ROOT/'poc/dlg-03/output/results.json';d6=ROOT/'poc/dlg-06/output/results.json';d7=ROOT/'poc/dlg-07/output/results.json';r2=json.loads(d2.read_text());r3=json.loads(d3.read_text());r6=json.loads(d6.read_text());r7=json.loads(d7.read_text());ds_nom=next(r for r in r2 if r['fixture']['id']=='nominal-fragment');bundle=next(r for r in r3 if r['fixture']['id']=='nominal-fragment');erg=next(a for a in bundle['analyses'] if a['producer']=='ACE_ERG')
