 integrated={'sources':{'dlg06_results_sha256':sha(d6),'dlg07_results_sha256':sha(d7)},'active_qud_ids':[q['id'] for q in actual_dgb['qud'] if q['status']=='active'],'fragment_observation':actual_fragment,'completion_candidates':actual_candidates,'selected_candidate_id':next((c['candidate_id'] for c in actual_candidates if c['valid']),None),'state_update':'none' if not any(c['valid'] for c in actual_candidates) else 'candidate available','reason':'resolved color QUD cannot be reopened; active size QUD rejects a color fragment'}
 vals={'all_raw_fragments_unchanged':all(c['fragment_observation']['raw']==next(s[3] for s in specs if s[0]==c['id']) for c in cases),'same_fragment_differs_by_qud':next(c for c in cases if c['id']=='fr-color')['completion_candidates'][0]['completion']!=next(c for c in cases if c['id']=='fr-wine')['completion_candidates'][0]['completion'],'question_echo_not_answer':next(c for c in cases if c['id']=='fr-echo')['completion_candidates'][0]['discourse_attachment']['relation']=='Clarification_question','all_selected_have_support_bindings_attachment':all((x:=c['completion_candidates'][0])['supports'] and x['bindings'] and x['discourse_attachment'] for c in cases),'all_rejections_explained':all(x.get('rejection_reason') for c in cases for x in c['completion_candidates'] if not x['valid']),'english_erg_runtime_parse':erg_red_ok,'dlg02_and_dlg03_artifacts_used':ds_nom['ok'] and erg['status']=='parsed','actual_dlg06_qud_consumed':{c['qud_id'] for c in actual_candidates}=={q['id'] for q in actual_dgb['qud']},'actual_inactive_qud_rejected':next(c for c in actual_candidates if c['qud_id']=='q1')['rejection_reason']=='QUD is not active','actual_type_mismatch_rejected':next(c for c in actual_candidates if c['qud_id']=='q2')['rejection_reason']=='fragment type Color mismatches active QUD type Size','actual_no_unsupported_isu_update':integrated['selected_candidate_id'] is None and integrated['state_update']=='none','upstream_dlg07_no_decision_policy_confirmed':r7['integrated_dgb_candidates']['selection']['candidate_id'] is None};assert all(vals.values()),vals
